import { SheetPage } from '../../slots/defs/sheetPage';
import { live, useClaims } from '../claims/claims';
import { STATUSES, useStatusCounts } from '../header/totals';
import { GRADES, gradeOn, usePeople } from '../people/people';
import { periodDue, usePeriods } from '../periods/periods';
import { personDue, sum, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';

/** The sheet's summary, worked out from the same figures the lists show. Per grade: the people on it on the sheet's
 *  today (retired people excluded) and their due-totals added up (skipping n/a). Per period: its due-total. Per
 *  status: how many of the sheet's claims have it. */
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const periods = usePeriods(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);

  const active = (people.data ?? []).filter((p) => p.retiredFrom === null);
  const onGrade = (grade: string) => active.filter((p) => gradeOn(p, late.today) === grade);
  const gradeDue = (grade: string) =>
    sum(
      onGrade(grade).map((p) =>
        personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p]), rates.data, p, late, floor),
      ),
    );
  const withStatus = useStatusCounts(sheetId);

  return (
    <section data-testid="summary">
      <h3>Summary</h3>
      <table data-testid="summary-grades">
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
          </tr>
        </thead>
}

/** A person's patrons (names, sorted), their backing (their patrons' due-totals added up, skipping n/a; 0.00 with no
 *  patrons), and the picker that names another person on the sheet as a patron. A refused add shows the row's
 *  patron error. */
function PersonPatrons({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const people = usePeople(sheetId);
  const patrons = usePatrons(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (patronId: number) =>
      postJson<Patron>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/patrons`, { patronId, by: user }),
    onSuccess: () => {
      setChosen('');
      return queryClient.invalidateQueries({ queryKey: patronsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  const mine = (patrons.data ?? [])
    .filter((p) => p.personId === person.id)
    .map((p) => people.data?.find((q) => q.id === p.patronId))
    .filter((p): p is Person => p !== undefined);
  const names = mine.map((p) => p.name).sort((a, b) => a.localeCompare(b));
  const backing = sum(
    mine.map((p) =>
      personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p]), rates.data, p, late, floor),
    ),
  );
  const others = (people.data ?? []).filter((p) => p.id !== person.id);

  return (
    <>
      <td data-testid="person-patrons">{names.join(', ')}</td>
 *  and due-total as shown, one line per person in list order, retired people included. The file is made once the
 *  sheet's figures are no longer being re-read, so it holds what the screen shows. */
function ExportPeople({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const fetching = useIsFetching({ queryKey: ['sheet', sheetId] });
  const [wanted, setWanted] = useState(false);

  useEffect(() => {
    if (!wanted || fetching > 0 || !people.data) return;
    setWanted(false);
    const lines = ['name,grade,retired-from,due-total'];
    for (const p of people.data) {
      const due = personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p]), rates.data, p, late, floor);
      lines.push([p.name, p.grade, p.retiredFrom ?? '', due].map(csvValue).join(','));
    }
    const url = URL.createObjectURL(new Blob([lines.join('\n') + '\n'], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = `people-${sheetId}.csv`;
    document.body.appendChild(a);
    a.click();
    a.remove();

