python3 - <<'EOF'
p='features/rates/rates.ts'
s=open(p).read()
old='''/** A person's due-total: the figures of their claims that count (each at the rate, of the grade in force, on its
 *  date, with its late charge) added up; 'n/a' when their grade has no rate today and none of those claims has a
 *  figure. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: string): string {
  const counted = claims.filter(counts);
  const figures = counted.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late));
  if (rateFor(rates, gradeOn(person, late.today), late.today) === undefined && figures.every((f) => f === 'n/a')) return 'n/a';
  return sum(figures);
}
'''
new='''/** The sum of a person's figures: the figures of their claims that count (each at the rate, of the grade in force,
 *  on its date, with its late charge) added up; 'n/a' when their grade has no rate today and none of those claims has
 *  a figure. */
function personFigures(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: string): string {
  const counted = claims.filter(counts);
  const figures = counted.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late));
  if (rateFor(rates, gradeOn(person, late.today), late.today) === undefined && figures.every((f) => f === 'n/a')) return 'n/a';
  return sum(figures);
}

/** A person's due-total: the sum of their figures (see personFigures), at most the sheet's cap (null: none); 'n/a'
 *  is not capped. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: string, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap) ? shown(hundredths(cap)) : total;
}

/** A person's excess: how far the sum of their figures is above the sheet's cap; 0.00 when it is not (or with no
 *  cap, or an n/a due-total). */
export function personExcess(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: string, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap)
    ? shown(hundredths(total) - hundredths(cap))
    : '0.00';
}
'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)

p='features/settings/settings.ts'
s=open(p).read()
s=s.replace("(clerk-limit, floor: an amount","(clerk-limit, cap, floor: an amount")
s=s.replace('''/** The terms a sheet has until''','''/** The sheet's cap: the most a person's due-total may be (two decimals); null when blank (none). */
export function useCap(sheetId: string): string | null {
  const settings = useSettings(sheetId);
  return settings.data?.find((s) => s.key === 'cap')?.value ?? null;
}

/** The terms a sheet has until''')
open(p,'w').write(s)

import re
for p in ['features/summary/summary.slot.tsx','features/patrons/patrons.slot.tsx','features/export/export.slot.tsx','features/header/totals.ts','features/rates/rates.slot.tsx']:
    s=open(p).read()
    s=s.replace("import { useFloor, useLate } from '../settings/settings';","import { useCap, useFloor, useLate } from '../settings/settings';")
    s=s.replace("p, late, floor)","p, late, floor, cap)").replace("person, late, floor)","person, late, floor, cap)")
    # add cap hook after floor hooks in functions that use personDue
    s=re.sub(r"(\n(\s*)const floor = useFloor\(sheetId\);)(?=((?!\nfunction|\nexport function).)*?personDue)", r"\1\n\2const cap = useCap(sheetId);", s, flags=re.S)
    open(p,'w').write(s)
EOF
grep -n 'useCap\|cap)' features/*/*.ts*

